input.command:
git checkout -q -b conductor/vercel-services origin/main && cat > vercel.json <<'EOF'
{
  "$schema": "https://openapi.vercel.sh/vercel.json",
  "services": {
    "web": {
      "root": ".",
      "framework": "other",
      "installCommand": "pip install uv && uv sync",
      "buildCommand": "uv run reflex export --frontend-only && mkdir -p frontend && unzip -o frontend.zip -d frontend",
      "outputDirectory": "frontend"
    }
  },
  "rewrites": [
    {
      "source": "/(.*)",
      "destination": {
        "service": "web"
      }
    }
  ]
}
EOF
python3 -m json.tool vercel.json >/dev/null && echo ok
